<?php
declare(strict_types=1);
require_once __DIR__.'/../config/auth.php';
require_once __DIR__.'/../config/periodos-financieros.php';
auth_require(['ADMIN']);
$autoload=__DIR__.'/../vendor/autoload.php';if(!is_file($autoload)){http_response_code(503);exit('Generador PDF no instalado. Ejecuta composer install/update en el servidor.');}require_once $autoload;
use Dompdf\Dompdf;use Dompdf\Options;
$config=require __DIR__.'/../config/database.php';
$pdo=new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
function esc(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function money(float|int|string|null $n):string{return '$'.number_format((float)$n,2,'.',',');}
function monthName(string $ym):string{[$y,$m]=array_map('intval',explode('-',$ym));$ms=[1=>'Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];return ($ms[$m]??$ym).' '.$y;}
function labelTipo(string $t):string{return match($t){'EFECTIVO_A_PROA'=>'Efectivo entregado a PROA','TRANSFERENCIA_A_PROA'=>'Transferencia a PROA','PAGO_DIRECTO_PROA'=>'Pago directo de alumno en PROA','COMISION_RECIBIDA_PROA'=>'Comisión manual antigua',default=>$t};}
try{
    $periodo=financiero_validar_periodo((string)($_GET['periodo']??date('Y-m')));
    $st=$pdo->query("SELECT id,porcentaje_mensualidad_socio,porcentaje_intensivo_socio,porcentaje_inscripcion_socio FROM sedes WHERE clave='MONTEVERDE' AND activo=1 LIMIT 1");
    $site=$st->fetch();if(!$site)throw new RuntimeException('La sede Monteverde no está configurada');
    $fin=financiero_totales($pdo,$site,$periodo);
    $rango=$fin['rango'];
    $desde=$rango['inicio'].' 00:00:00';
    $hasta=(new DateTimeImmutable($rango['cierre']))->modify('+1 day')->format('Y-m-d').' 00:00:00';
    $mens=(float)$fin['mensualidades_total'];$int=(float)$fin['intensivos_total'];$ins=(float)$fin['inscripciones_total'];
    $proaMens=$mens*((float)$site['porcentaje_mensualidad_socio']/100);$proaInt=$int*((float)$site['porcentaje_intensivo_socio']/100);$proaIns=$ins*((float)$site['porcentaje_inscripcion_socio']/100);$obligacion=$proaMens+$proaInt+$proaIns;
    $st=$pdo->prepare("SELECT id,periodo,alumno_proa_nombre,importe,observacion,created_at FROM comisiones_proa WHERE periodo=:p ORDER BY created_at,alumno_proa_nombre");$st->execute([':p'=>$periodo.'-01']);$comisiones=$st->fetchAll();$totalComisiones=0.0;foreach($comisiones as $c)$totalComisiones+=(float)$c['importe'];
    $st=$pdo->prepare("SELECT m.id,m.fecha,m.tipo,m.importe,m.alumno_nombre,m.referencia,m.observacion,m.estado,m.motivo_anulacion,m.created_at,u.usuario created_by_usuario FROM conciliacion_proa_movimientos m LEFT JOIN usuarios u ON u.id=m.created_by WHERE m.fecha>=:d AND m.fecha<:h ORDER BY m.fecha,m.created_at");$st->execute([':d'=>$desde,':h'=>$hasta]);$movs=$st->fetchAll();
    $efectivo=0.0;$transferencias=0.0;$directos=0.0;foreach($movs as $m){if(($m['estado']??'')!=='ACTIVO')continue;$v=(float)$m['importe'];if($m['tipo']==='EFECTIVO_A_PROA')$efectivo+=$v;elseif($m['tipo']==='TRANSFERENCIA_A_PROA')$transferencias+=$v;elseif($m['tipo']==='PAGO_DIRECTO_PROA')$directos+=$v;}
    $entregado=$efectivo+$transferencias;$saldo=$obligacion-$totalComisiones-$entregado-$directos;$situacion=abs($saldo)<.005?'CUADRADO':($saldo>0?'HACHE DEBE A PROA':'PROA DEBE A HACHE');$estadoMonto=abs($saldo)<.005?money(0):money(abs($saldo));
    $commissionRows='';foreach($comisiones as $c){$commissionRows.='<tr><td>'.esc(substr((string)$c['created_at'],0,10)).'</td><td>'.esc((string)$c['alumno_proa_nombre']).'</td><td>'.esc((string)($c['observacion']?:'—')).'</td><td class="num">'.money($c['importe']).'</td></tr>';}if($commissionRows==='')$commissionRows='<tr><td colspan="4" class="empty">Sin comisiones PROA en este periodo.</td></tr>';
    $movementRows='';foreach($movs as $m){$detalle=trim(implode(' · ',array_filter([(string)($m['alumno_nombre']??''),(string)($m['referencia']??''),(string)($m['observacion']??'')])));if($detalle==='')$detalle='—';$estado=(string)$m['estado'];$movementRows.='<tr class="'.($estado==='ANULADO'?'void':'').'"><td>'.esc(substr((string)$m['fecha'],0,16)).'</td><td>'.esc(labelTipo((string)$m['tipo'])).'</td><td>'.esc($detalle).'</td><td class="num">'.money($m['importe']).'</td><td>'.esc($estado).($estado==='ANULADO'&&$m['motivo_anulacion']?' · '.esc((string)$m['motivo_anulacion']):'').'</td></tr>';}if($movementRows==='')$movementRows='<tr><td colspan="5" class="empty">Sin movimientos manuales en este periodo.</td></tr>';
    $generated=(new DateTimeImmutable('now',new DateTimeZone('America/Cancun')))->format('d/m/Y H:i');
    $rangeLabel=(new DateTimeImmutable($rango['inicio']))->format('d/m/Y').' – '.(new DateTimeImmutable($rango['cierre']))->format('d/m/Y');
    $html='<!doctype html><html lang="es"><head><meta charset="utf-8"><style>@page{margin:28px 32px 34px}*{box-sizing:border-box}body{font-family:DejaVu Sans,Arial,sans-serif;color:#172033;font-size:10px;margin:0}.brand{background:#123b5d;color:#fff;padding:20px 22px;border-radius:12px}.brand h1{margin:0 0 3px;font-size:23px}.brand p{margin:0;color:#dce8f1}.meta{width:100%;margin:10px 0 16px;border-collapse:collapse}.meta td{padding:2px 0;color:#66778a}.meta td:last-child{text-align:right}.cards{width:100%;border-collapse:separate;border-spacing:6px;margin-left:-6px;margin-right:-6px}.cards td{border:1px solid #dfe7ee;background:#f8fafc;border-radius:9px;padding:10px}.cards .primary{background:#172033;color:#fff;border-color:#172033}.label{text-transform:uppercase;color:#718096;font-size:7.6px;letter-spacing:.45px}.primary .label{color:#d8e0e8}.value{font-size:16px;font-weight:bold;margin-top:4px}.section{margin-top:14px;border:1px solid #dfe7ee;border-radius:11px;padding:12px}.section h2{margin:0 0 8px;font-size:14px}.formula{width:100%;border-collapse:separate;border-spacing:6px;margin-left:-6px}.formula td{width:33.33%;background:#f8fafc;border:1px solid #e4e9ee;border-radius:8px;padding:9px}.formula b{display:block;margin-top:4px;font-size:12px}.detail{width:100%;border-collapse:collapse}.detail th{background:#eef3f7;text-transform:uppercase;font-size:7.5px;letter-spacing:.35px;color:#566779;text-align:left;padding:7px}.detail td{padding:7px;border-bottom:1px solid #e8edf2;vertical-align:top}.num{text-align:right!important;font-weight:bold}.empty{text-align:center;color:#718096;padding:12px!important}.status{margin-top:16px;padding:15px;border-radius:11px;background:#172033;color:#fff}.status span{display:block;text-transform:uppercase;font-size:8px;letter-spacing:.5px;color:#cad4df}.status b{display:block;font-size:19px;margin-top:4px}.void{color:#9aa5b1}.note{margin-top:9px;color:#6d7c8c;font-size:8.5px;line-height:1.45}.foot{margin-top:16px;border-top:1px solid #dfe7ee;padding-top:8px;color:#7b8795;font-size:8px}</style></head><body><div class="brand"><h1>Hache Natación</h1><p>Conciliación mensual PROA · Monteverde</p></div><table class="meta"><tr><td><b>Periodo:</b> '.esc(monthName($periodo)).' · '.esc($rangeLabel).'</td><td><b>Generado:</b> '.$generated.'</td></tr></table><table class="cards"><tr><td class="primary"><div class="label">Obligación PROA</div><div class="value">'.money($obligacion).'</div></td><td><div class="label">Entregado a PROA</div><div class="value">'.money($entregado).'</div></td><td><div class="label">Pagos directos</div><div class="value">'.money($directos).'</div></td><td><div class="label">Comisiones</div><div class="value">'.money($totalComisiones).'</div></td></tr></table><div class="section"><h2>Cómo se forma la obligación</h2><table class="formula"><tr><td><span class="label">Mensualidades del periodo</span><b>'.money($mens).' × '.number_format((float)$site['porcentaje_mensualidad_socio'],0).'% = '.money($proaMens).'</b></td><td><span class="label">Intensivos del periodo</span><b>'.money($int).' × '.number_format((float)$site['porcentaje_intensivo_socio'],0).'% = '.money($proaInt).'</b></td><td><span class="label">Inscripciones del periodo</span><b>'.money($ins).' × '.number_format((float)$site['porcentaje_inscripcion_socio'],0).'% = '.money($proaIns).'</b></td></tr></table><div class="note">La conciliación usa el mismo periodo financiero configurable que Reportes y Cierre mensual. Las mensualidades se asignan a su periodo; los intensivos por fecha de inicio del curso y las inscripciones por fecha de inscripción.</div></div><div class="section"><h2>Comisiones PROA</h2><table class="detail"><thead><tr><th>Fecha</th><th>Alumno PROA</th><th>Observación</th><th class="num">Importe</th></tr></thead><tbody>'.$commissionRows.'</tbody></table></div><div class="section"><h2>Movimientos de conciliación</h2><table class="detail"><thead><tr><th>Fecha</th><th>Movimiento</th><th>Detalle</th><th class="num">Importe</th><th>Estado</th></tr></thead><tbody>'.$movementRows.'</tbody></table></div><div class="status"><span>Estado de la conciliación · '.esc(monthName($periodo)).'</span><b>'.esc($situacion).' · '.$estadoMonto.'</b></div><div class="note">Saldo = obligación PROA − comisiones automáticas − efectivo/transferencias entregadas − pagos recibidos directamente por PROA.</div><div class="foot">Documento emitido desde Hache Natación.</div></body></html>';
    $options=new Options();$options->set('defaultFont','DejaVu Sans');$options->set('isRemoteEnabled',false);$pdf=new Dompdf($options);$pdf->loadHtml($html,'UTF-8');$pdf->setPaper('A4','portrait');$pdf->render();$pdf->stream('conciliacion-proa-'.$periodo.'.pdf',['Attachment'=>true]);
}catch(InvalidArgumentException $e){http_response_code(422);echo esc($e->getMessage());
}catch(Throwable $e){error_log('[conciliacion-proa-pdf] '.$e->getMessage());http_response_code(500);echo 'No se pudo generar el reporte de conciliación.';}
